from z3 import *

n = 21
# variables x[i][j] for i<j
x = {}
for i in range(n):
    for j in range(i+1, n):
        x[(i,j)] = Bool(f"x_{i}_{j}")

s = Solver()

# degree constraints: each vertex degree between 4 and 6
for v in range(n):
    neighbors = []
    for u in range(n):
        if u == v: continue
        i, j = (u, v) if u < v else (v, u)
        neighbors.append(x[(i,j)])
    # sum >= 4
    s.add(PbGe([(n, 1) for n in neighbors], 4))
    # sum <= 6
    s.add(PbLe([(n, 1) for n in neighbors], 6))

# no triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(Or(Not(x[(i,j)]), Not(x[(i,k)]), Not(x[(j,k)])))

# no 4-cycles: for any distinct u,v,w,x, not (uw, vw, ux, vx)
# i.e., no two vertices share two common neighbors
# We can iterate over unordered pairs {u,v} and unordered pairs {w,x} disjoint from {u,v}
count = 0
for u in range(n):
    for v in range(u+1, n):
        for w in range(n):
            if w == u or w == v: continue
            for x in range(w+1, n):
                if x == u or x == v: continue
                # forbid edges u-w, v-w, u-x, v-x all present
                s.add(Or(Not(x[(min(u,w), max(u,w))]),
                         Not(x[(min(v,w), max(v,w))]),
                         Not(x[(min(u,x), max(u,x))]),
                         Not(x[(min(v,x), max(v,x))])))
                count += 1
print("4-cycle clauses:", count)
print("Total assertions:", len(s.assertions()))

m = s.model()
edges = []
for i in range(n):
    for j in range(i+1, n):
        if is_true(m[edge[(i,j)]]):
            edges.append((i,j))

print("Number of edges:", len(edges))
print("Edges:", edges)

# verify degrees
deg = [0]*n
for u,v in edges:
    deg[u] += 1
    deg[v] += 1
print("Degrees:", deg)
print("Min degree:", min(deg), "Max degree:", max(deg))

# verify no triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            if (i,j) in edges and (i,k) in edges and (j,k) in edges:
                print("TRIANGLE!", i,j,k)

# verify no 4-cycles
# build adjacency
adj = [set() for _ in range(n)]
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

for u in range(n):
    for v in range(u+1, n):
        common = adj[u] & adj[v]
        if len(common) >= 2:
            print("4-CYCLE!", u, v, common)

