from collections import deque

def shortest_cycle(adj, n):
    best = float('inf')
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    # found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    best = min(best, cycle_len)
        if best == 5:
            break
    return best

